@extends('layouts.customer') @section('title','Order Eggs') @section('content')<div class="mx-auto max-w-[1500px] px-8 py-10"><h2 class="text-4xl font-bold">Our Products</h2><p class="mt-2 text-slate-500">Choose the eggs you need and submit an inquiry.</p><form method="POST" action="{{route('customer.order.store')}}" class="mt-8 grid gap-6 xl:grid-cols-3 xl:items-start">@csrf<div class="grid gap-6 md:grid-cols-3 xl:col-span-2">@foreach($products as $product)<div class="product-card card p-5" data-id="{{$product->id}}" data-name="{{$product->product_name}}" data-price="{{$product->price}}">@include('partials.egg-image')<h3 class="mt-4 text-lg font-bold">{{$product->product_name}}</h3><p class="mt-1 text-lg font-bold">₱{{number_format($product->price,2)}}</p><div class="mt-4 flex items-center justify-between rounded-lg border border-[#d8e5f3] bg-[#f8fbff] px-3 py-2"><button type="button" class="minus px-3">−</button><span class="qty font-semibold">0</span><button type="button" class="plus px-3">+</button></div><button type="button" class="add btn-primary mt-3 w-full">Add to Inquiry</button></div>@endforeach<div class="card p-6 md:col-span-3"><h3 class="text-xl font-bold">Your Inquiry</h3><div id="items" class="mt-4 space-y-2"></div><div class="mt-4 flex justify-between border-t border-[#d8e5f3] pt-4"><span class="font-semibold text-slate-500">Estimated Total</span><strong id="total">₱0.00</strong></div></div></div><div class="card p-6"><h3 class="text-xl font-bold">Customer Information</h3><div class="mt-4 space-y-4"><input class="input" name="customer_name" placeholder="Name" required><input class="input" name="contact" placeholder="Contact" required><input class="input" name="email" type="email" placeholder="Email"><textarea class="input" name="address" rows="3" placeholder="Address"></textarea></div><div id="hidden"></div><button class="btn-primary mt-6 w-full" type="submit">Submit Inquiry</button></div></form></div><script>document.addEventListener('DOMContentLoaded',()=>{const s=new Map(),items=document.getElementById('items'),hidden=document.getElementById('hidden'),total=document.getElementById('total');function r(){items.innerHTML='';hidden.innerHTML='';let t=0;s.forEach((v,k)=>{t+=v.q*v.p;items.innerHTML+=`<div class="flex justify-between rounded-lg border border-[#d8e5f3] p-3 text-sm"><span>${v.n} × ${v.q}</span><b>₱${(v.q*v.p).toFixed(2)}</b></div>`;hidden.innerHTML+=`<input type="hidden" name="items[${k}][product_id]" value="${k}"><input type="hidden" name="items[${k}][quantity]" value="${v.q}">`});total.textContent='₱'+t.toFixed(2)}document.querySelectorAll('.product-card').forEach(c=>{const id=c.dataset.id,n=c.dataset.name,p=Number(c.dataset.price),q=c.querySelector('.qty');const set=x=>{x=Math.max(0,x);q.textContent=x;x?s.set(id,{n,p,q:x}):s.delete(id);r()};c.querySelector('.plus').onclick=()=>set(Number(q.textContent)+1);c.querySelector('.minus').onclick=()=>set(Number(q.textContent)-1);c.querySelector('.add').onclick=()=>set(Math.max(1,Number(q.textContent)));});});</script>@endsection
